# --- Scenario: a mobile screen shows a user, their last 5 orders,
#     each with its line items and the product name/thumbnail. ---

# ============ REST (3+ round trips, over-fetch per call) =====================
#   GET /users/42                              -> User JSON with 40 fields
#   GET /users/42/orders?limit=5               -> Array of 5 Order JSONs
#   GET /orders/{id}/items  (x5)               -> 5 item arrays
#   GET /products/{sku}     (x N items)        -> N product JSONs
# Many sequential/parallel requests; clients stitch on-device.

# ============ GraphQL (1 query, exactly what the UI needs) ===================
query OrderHistoryScreen($userId: ID!) {
  user(id: $userId) {
    id
    displayName
    avatarUrl
    orders(last: 5) {
      id
      placedAt
      total { amount currency }
      items {
        quantity
        product {
          sku
          name
          thumbnailUrl
        }
      }
    }
  }
}

# One round-trip; the server walks the graph, batching via DataLoader.
# The mobile client declares the exact field set needed for this screen.

# ============ gRPC (typed RPC, strong perf, not browser-native) ==============
# user_service.proto
syntax = "proto3";
package acme.user.v1;

service UserService {
  rpc GetUserWithOrders (GetUserWithOrdersRequest)
      returns (GetUserWithOrdersResponse);
}

message GetUserWithOrdersRequest { string user_id = 1; int32 last = 2; }

message GetUserWithOrdersResponse {
  User user = 1;
  repeated Order orders = 2;
}

# Fastest on the wire (protobuf + HTTP/2 multiplexing); best for service-to-service.
# Needs gRPC-Web + a proxy for browsers; tooling cost higher than REST.

# Spring-side resolver sketch for the GraphQL version:

@Controller
class OrderHistoryResolvers {

    @QueryMapping
    User user(@Argument String id) { return users.find(id); }

    @SchemaMapping(typeName = "User", field = "orders")
    List<Order> orders(User user, @Argument int last) {
        return orderService.lastN(user.id(), last);
    }

    // Batched resolver for Product to avoid N+1 on items.product
    @BatchMapping
    Map<OrderItem, Product> product(List<OrderItem> items) {
        List<String> skus = items.stream().map(OrderItem::sku).toList();
        Map<String, Product> bySku = productService.getAll(skus);
        return items.stream().collect(Collectors.toMap(i -> i, i -> bySku.get(i.sku())));
    }
}

Spring Boot looks for `.graphqls` (or `.gqls`) files in `src/main/resources/graphql/` and merges them into one schema automatically. This convention means you don't need to register schema files manually or point to them in configuration — drop them in the right folder and they're discovered.

For anything beyond a toy project, split schemas by domain. A `book.graphqls` and `author.graphqls` file merge seamlessly, making schema files manageable as the API grows.

```graphql
# src/main/resources/graphql/schema.graphqls
type Query {
  book(id: ID!): Book
  books: [Book!]!
}

type Mutation {
  createBook(title: String!, authorId: ID!): Book!
}

type Book {
  id: ID!
  title: String!
  author: Author!          # nested relationship — resolved by @SchemaMapping
}

type Author {
  id: ID!
  name: String!
}
```

The schema is a contract between your API and its clients. Non-null markers (`!`) are commitments — if `author` is declared `Author!` and the resolver throws an error, null bubbling will erase the parent `Book` from the response. Start nullable and tighten later as you gain confidence in resolver reliability.

Resolvers in Spring for GraphQL are plain `@Controller` beans — the same stereotype as REST controllers. `@QueryMapping` maps to schema `Query` fields, `@MutationMapping` maps to `Mutation` fields, and `@SchemaMapping` resolves nested type fields. Method names must match the schema field names by convention.

```java
@Controller
public class BookController {

    private final BookService bookService;

    public BookController(BookService bookService) {
        this.bookService = bookService;
    }

    @QueryMapping                              // maps to Query.books
    public List<Book> books() {
        return bookService.findAll();
    }

    @QueryMapping                              // maps to Query.book
    public Book book(@Argument Long id) {
        return bookService.findById(id);
    }

    @MutationMapping                           // maps to Mutation.createBook
    public Book createBook(@Argument String title, @Argument Long authorId) {
        return bookService.create(title, authorId);
    }

    @SchemaMapping                             // maps to Book.author
    public Author author(Book book) {
        return bookService.findAuthor(book.getAuthorId());
    }
}
```

The `@SchemaMapping` method for `author` receives the parent `Book` object as its first parameter — Spring infers the parent type and field name from the method signature. This is where the N+1 problem hides: with 50 books, `author()` gets called 50 times. Replace the direct repository call with a `DataLoader` early — retrofitting it later is painful.

For local development, enable GraphiQL in `application.properties` so the team can explore the schema interactively before any client code exists.

```properties
spring.graphql.graphiql.enabled=true
spring.graphql.graphiql.path=/graphiql
```

Queries and mutations are plain HTTP — your existing load balancers, CDN rules, and Spring Security filter chains work unchanged. Subscriptions require persistent connections, which means a different infrastructure stack.

In Spring for GraphQL, subscriptions use the `graphql-ws` WebSocket subprotocol. The resolver returns a reactive `Flux` that the framework converts into WebSocket frames pushed to the client. A common pattern uses Reactor `Sinks` to bridge between mutation handlers (that produce events) and subscription resolvers (that consume them).

```java
@Controller
public class OrderSubscriptionController {

    private final Sinks.Many<Order> orderSink =
        Sinks.many().multicast().onBackpressureBuffer();

    @SubscriptionMapping
    public Flux<Order> orderPlaced() {
        return orderSink.asFlux();     // clients receive each new order
    }

    public void publishOrder(Order order) {
        orderSink.tryEmitNext(order);  // called from the mutation handler
    }
}
```

The infrastructure implications are real. WebSocket connections are long-lived, so load balancers need sticky sessions or connection-aware routing. Auth tokens expire, but the WebSocket stays open — you need a token refresh mechanism that doesn't drop every active listener. And backpressure matters: if a client can't consume events as fast as the server produces them, the buffer grows until memory pressure becomes a problem. Set bounded buffers and handle overflow explicitly.

The batch function is where DataLoader converts individual key lookups into a bulk operation. In Spring for GraphQL, you implement `BatchLoaderWithContext<K, V>` and return a `CompletionStage<List<V>>`. The contract has one non-negotiable rule: **the returned list must match the input key list by position and size**.

DataLoader maps results to parents by array index, not by key lookup. If the input keys are `[3, 1, 7]` and your query returns authors sorted by ID as `[author-1, author-3, author-7]`, author-1 gets attached to the parent that requested key 3. The data silently corrupts.

The safe pattern is to query into a `Map`, then stream over the input keys to produce the ordered result list.

```java
@Override
public CompletionStage<List<Author>> load(List<Long> keys,
                                           BatchLoaderEnvironment env) {
    Map<Long, Author> byId = authorRepository.findAllById(keys)
        .stream()
        .collect(Collectors.toMap(Author::getId, Function.identity()));

    // Preserve input order — DataLoader matches by position, not by key
    List<Author> ordered = keys.stream()
        .map(byId::get)        // null if author doesn't exist for this key
        .collect(Collectors.toList());

    return CompletableFuture.completedFuture(ordered);
}
```

The `byId::get` call can return `null` for keys without matching rows — that's valid. What's not valid is returning fewer elements than the input list, or returning them in a different order. Both cause `DataLoader` to throw or silently misalign data.

DataLoader maintains a per-request memoization cache. If two books share `authorId = 5`, the batch function receives `5` only once — the second lookup hits the cache and returns the same object. This is usually desirable: it reduces query payload and ensures referential equality within a single response.

But the cache becomes a problem when a mutation modifies data mid-request. Imagine a GraphQL document that first runs a mutation to update an author's name, then queries books with that author. The DataLoader still holds the pre-mutation author object in its cache. The response shows stale data — the query portion returns the old name.

The fix is explicit cache invalidation. After the mutation completes, clear the loader for the affected key.

```java
@MutationMapping
public Author updateAuthor(@Argument Long id, @Argument String name,
                           DataLoader<Long, Author> authorLoader) {
    Author updated = authorService.updateName(id, name);
    authorLoader.clear(id);    // evict stale cached value
    return updated;
}
```

For registering loaders in Spring for GraphQL, implement `BatchLoaderRegistry` in a `@Configuration` class. Spring creates a fresh `DataLoaderRegistry` per request automatically — you don't manage lifecycle.

```java
@Configuration
public class LoaderConfig {
    @Bean
    public BatchLoaderRegistry batchLoaderRegistry(
            AuthorRepository authorRepo) {
        BatchLoaderRegistry registry = new DefaultBatchLoaderRegistry();
        registry.forTypePair(Long.class, Author.class)
            .registerBatchLoader((keys, env) -> {
                Map<Long, Author> map = authorRepo.findAllById(keys)
                    .stream().collect(Collectors.toMap(Author::getId, a -> a));
                return Flux.fromIterable(keys).map(map::get);
            });
        return registry;
    }
}
```

The per-request scope is critical for correctness. A globally shared DataLoader cache would serve stale data across requests and leak one user's data to another. Spring handles this automatically — each GraphQL execution gets an isolated loader registry.

This resolver passes every test and returns the right data. The problem isn't correctness — it's that the engine calls this method once per book in the result list, and each invocation performs its own database round trip.

```java
@SchemaMapping
public Author author(Book book) {
    // Called once per book — 200 books = 200 individual queries
    return authorRepository.findById(book.getAuthorId()).orElse(null);
}
```

With SQL logging enabled, the output reveals the explosion:

```sql
SELECT * FROM book;                      -- 1 query (root)
SELECT * FROM author WHERE id = 1;       -- per book
SELECT * FROM author WHERE id = 2;
SELECT * FROM author WHERE id = 3;
-- ... 197 more queries
SELECT * FROM author WHERE id = 200;     -- total: 201 queries
```

Each query is fast individually — maybe 2ms. But 201 × 2ms = 400ms just in database time, plus connection acquisition overhead. Under concurrent load, the connection pool (typically 10-20 connections) saturates, and requests start queuing.

DataLoader solves the N+1 by coordinating across independent resolvers. Instead of executing the database call immediately, each resolver registers a key and receives a `CompletableFuture`. After all resolvers at the current execution level have registered their keys, the engine dispatches one batch call.

```java
@Component
public class AuthorBatchLoader implements BatchLoaderWithContext<Long, Author> {

    private final AuthorRepository authorRepository;

    public AuthorBatchLoader(AuthorRepository authorRepository) {
        this.authorRepository = authorRepository;
    }

    @Override
    public CompletionStage<List<Author>> load(List<Long> keys,
                                               BatchLoaderEnvironment env) {
        // One query: SELECT * FROM author WHERE id IN (1, 2, 3, ... 200)
        Map<Long, Author> byId = authorRepository.findAllById(keys)
            .stream()
            .collect(Collectors.toMap(Author::getId, Function.identity()));

        // CRITICAL: return results in input key order — DataLoader matches by position
        return CompletableFuture.completedFuture(
            keys.stream().map(byId::get).collect(Collectors.toList())
        );
    }
}
```

The resolver signature changes to return `CompletableFuture<Author>` and accept the `DataLoader` as a parameter. Spring injects the named loader automatically.

```java
@SchemaMapping
public CompletableFuture<Author> author(Book book,
                                        DataLoader<Long, Author> authorLoader) {
    return authorLoader.load(book.getAuthorId());
    // All 200 load() calls accumulate, then ONE batch query fires
}
```

The SQL output is now constant regardless of list size:

```sql
SELECT * FROM book;                                    -- 1 query
SELECT * FROM author WHERE id IN (1,2,3,...,200);      -- 1 query
-- Total: 2 queries for any N
```

Two critical production safeguards: set `maxBatchSize` on the `DataLoaderOptions` to prevent unbounded `IN` clauses (some databases choke on 10,000-element IN lists), and verify that the `author_id` foreign key column is **indexed**. Batching fixes call count, not slow SQL — if the `IN` query hits a full table scan, you've replaced 200 fast queries with one enormous slow query.

Marking a field `!` (non-null) feels like good type safety — "this field always has a value." In practice, it's an error-propagation decision with severe consequences. When a non-null field's resolver throws an error, GraphQL doesn't just return null for that field — it can't, because the schema promised non-null. Instead, it **null-bubbles**: it nulls the parent object. If the parent is also non-null, it nulls the grandparent, and so on up the tree until it reaches a nullable ancestor.

A single failing resolver can erase an entire query response. Imagine a `books` query returning 50 results where one book's `author` resolver throws. If `author: Author!` and `Book` is in a non-null list `[Book!]!`, that one failure nulls the book, which invalidates the list element, which nulls the entire list, which nulls the entire `data` object. The client gets nothing — not even the 49 books that resolved successfully.

```graphql
# DANGEROUS — one author failure wipes all books
type Query {
  books: [Book!]!          # non-null list of non-null books
}
type Book {
  id: ID!
  title: String!
  author: Author!          # if this fails, Book becomes null → list invalid
}

# SAFER — partial results survive individual failures
type Query {
  books: [Book]!           # non-null list, but individual books can be null
}
type Book {
  id: ID!
  title: String!
  author: Author           # nullable — failure returns null, book survives
}
```

My rule: mark `id` and enum statuses as non-null (they're truly invariant). Default everything else to nullable until you have production confidence that the resolver never fails. Tightening nullability later is a non-breaking change. Loosening it is breaking.

Every list in a schema eventually needs pagination, filtering, or metadata. If you start with `books: [Book!]!`, adding pagination later is a breaking change — you have to introduce new arguments and return types that alter the response shape. The **Relay Connection** pattern solves this by designing pagination in from the start.

```graphql
type Query {
  books(first: Int, after: String, filter: BookFilter): BookConnection!
}

input BookFilter {
  status: BookStatus
  authorId: ID
}

type BookConnection {
  edges: [BookEdge!]!
  pageInfo: PageInfo!
  totalCount: Int!
}

type BookEdge {
  node: Book!
  cursor: String!          # opaque — clients must not parse or construct
}

type PageInfo {
  hasNextPage: Boolean!
  hasPreviousPage: Boolean!
  startCursor: String
  endCursor: String
}
```

The ceremony feels heavy for a list that "only has 20 items." But schemas outlive your assumptions — the list grows, clients want infinite scroll, and you need edge-level metadata (sort rank, relationship date). Connections give you room for all of this without breaking existing clients.

The cursor should be opaque — base64-encode the sort key plus a tie-breaker (usually the primary key) so clients can't construct cursors manually or depend on internal sort logic. If clients rely on cursor internals, you can't change your sort implementation without breaking them.

Mutations should use dedicated **input types** and return **payload types** that include a structured error list. This design enables three things: input validation that maps to form fields, partial success reporting, and schema evolution without version bumps.

```graphql
input CreateBookInput {
  title: String!
  authorId: ID!
  tags: [String!]
}

type CreateBookPayload {
  book: Book                  # null on validation failure
  errors: [UserError!]!       # empty on success
}

type UserError {
  field: String               # maps to the input field, e.g., "title"
  message: String!
}

type Mutation {
  createBook(input: CreateBookInput!): CreateBookPayload!
}
```

The distinction between `UserError` (in the payload) and the top-level `errors` array is critical. `UserError` represents domain-level validation failures — "title too short," "author not found" — that clients can map to specific UI fields. The top-level `errors` array is for unexpected system failures — network errors, resolver bugs, permission violations. Mixing these two categories forces clients to string-parse error messages to determine if they should show a form validation message or a system error toast.

Use **enums** for any field with a fixed set of values — `BookStatus`, `OrderState`, `UserRole`. Strings masquerading as enums (`status: String!` where valid values are "DRAFT", "PUBLISHED", "ARCHIVED") bypass schema validation and codegen. A client sending `status: "draft"` (lowercase) gets a runtime error instead of a schema validation error. Enums catch these at the GraphQL parsing layer before your resolver code runs.

Authentication happens before the GraphQL engine runs. A `OncePerRequestFilter` extracts the JWT from the `Authorization` header, validates it, builds a `UsernamePasswordAuthenticationToken`, and sets it in the `SecurityContext`. This is identical to REST — GraphQL doesn't change anything at this layer.

```java
@Configuration
@EnableWebSecurity
@EnableMethodSecurity       // required for @PreAuthorize on resolver methods
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(AbstractHttpConfigurer::disable)    // stateless API — no CSRF
            .sessionManagement(s -> s.sessionCreationPolicy(STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/graphiql").permitAll()
                .requestMatchers("/graphql").authenticated()
            )
            .addFilterBefore(jwtAuthFilter,
                UsernamePasswordAuthenticationFilter.class)
            .build();
    }
}
```

The `/graphql` endpoint requires authentication, so anonymous users get a 401 before the engine runs. GraphiQL is open for development convenience. The `@EnableMethodSecurity` annotation is critical — without it, `@PreAuthorize` annotations on resolver methods are silently ignored, which is a common source of security bugs where teams think they have authorization but don't.

With `@EnableMethodSecurity` active, you can annotate resolver methods with `@PreAuthorize` to enforce role checks at the operation level. This gives you per-operation authorization without custom infrastructure.

```java
@Controller
public class BookController {

    private final BookService bookService;

    public BookController(BookService bookService) {
        this.bookService = bookService;
    }

    @QueryMapping
    @PreAuthorize("isAuthenticated()")        // any logged-in user
    public List<Book> books() {
        return bookService.findAll();
    }

    @MutationMapping
    @PreAuthorize("hasRole('EDITOR')")        // only editors can create
    public Book createBook(@Argument CreateBookInput input) {
        return bookService.create(input);
    }

    @MutationMapping
    @PreAuthorize("hasRole('ADMIN')")         // only admins can delete
    public Boolean deleteBook(@Argument Long id) {
        return bookService.delete(id);
    }

    @QueryMapping
    @PreAuthorize("isAuthenticated()")
    public List<Book> myBooks(@AuthenticationPrincipal UserDetails user) {
        return bookService.findByOwner(user.getUsername());
    }
}
```

The `@AuthenticationPrincipal` injection makes the resolver testable — you pass a mock `UserDetails` in tests instead of setting up a full security context. For field-level authorization (e.g., hiding `salary` from non-HR users), push the check into the service layer rather than the resolver — the resolver should call `bookService.findWithAccess(user)` and let the service decide what fields to populate.

When `@PreAuthorize` rejects a call, Spring throws `AccessDeniedException`. In REST, this becomes HTTP 403. But GraphQL always returns HTTP 200 — the error must appear in the `errors` array of the JSON response, not as an HTTP status code. Without explicit handling, the default behavior leaks implementation details or produces confusing responses.

Register a `DataFetcherExceptionResolver` that catches security exceptions and converts them to typed GraphQL errors.

```java
@Component
public class SecurityExceptionResolver extends DataFetcherExceptionResolverAdapter {

    @Override
    protected GraphQLError resolveToSingleError(Throwable ex,
                                                 DataFetchingEnvironment env) {
        if (ex instanceof AccessDeniedException) {
            return GraphqlErrorBuilder.newError(env)
                .message("You do not have permission for this operation")
                .errorType(ErrorType.FORBIDDEN)
                .extensions(Map.of("code", "FORBIDDEN"))
                .build();
        }
        if (ex instanceof AuthenticationException) {
            return GraphqlErrorBuilder.newError(env)
                .message("Authentication required")
                .errorType(ErrorType.UNAUTHORIZED)
                .extensions(Map.of("code", "UNAUTHENTICATED"))
                .build();
        }
        return null;  // let other resolvers handle non-security exceptions
    }
}
```

The `extensions` map is what client code uses to programmatically detect auth failures. Clients check `error.extensions.code === "FORBIDDEN"` instead of parsing human-readable messages. Without this resolver, the client gets a generic `INTERNAL_ERROR` classification that doesn't distinguish authorization failures from server bugs — making client-side error handling impossible.

# Relay Connection spec for cursor-based pagination ---------------------------
type Query {
  posts(first: Int, after: String, last: Int, before: String,
        filter: PostFilter, sort: PostSort = CREATED_AT_DESC): PostConnection!
}

type PostConnection {
  edges:    [PostEdge!]!
  nodes:    [Post!]!          # convenience for clients that don't need cursors
  pageInfo: PageInfo!
}
type PostEdge {
  node:   Post!
  cursor: String!              # opaque base64 token -- clients must not parse
}
type PageInfo {
  hasNextPage:     Boolean!
  hasPreviousPage: Boolean!
  startCursor:     String
  endCursor:       String
}

# Query: first page
query FirstPage { posts(first: 20) { pageInfo { endCursor hasNextPage }
                                     edges { cursor node { id title } } } }
# Query: next page using endCursor from previous response
query NextPage  { posts(first: 20, after: "eyJ0Ijox...") { ... } }

@Controller
class PostGraphQlController {

    private final PostRepository repo;
    private final CursorCodec cursorCodec;     // base64(JSON of the keyset)

    // Connection resolver — takes Relay-style args, returns Connection<Post>
    @QueryMapping
    Connection<Post> posts(@Argument Integer first,
                           @Argument String  after,
                           @Argument Integer last,
                           @Argument String  before,
                           @Argument PostFilter filter,
                           @Argument PostSort   sort) {
        int pageSize = Optional.ofNullable(first).or(() -> Optional.ofNullable(last)).orElse(20);
        Keyset anchor = after != null ? cursorCodec.decode(after)
                       : before != null ? cursorCodec.decode(before)
                       : null;

        // Keyset pagination against Postgres — stable under concurrent inserts
        List<Post> page = repo.findPage(filter, sort, anchor, pageSize + 1);
        boolean hasMore = page.size() > pageSize;
        if (hasMore) page = page.subList(0, pageSize);

        List<Edge<Post>> edges = page.stream()
            .map(p -> new DefaultEdge<>(p,
                    cursorCodec.encode(new Keyset(p.createdAt(), p.id()))))
            .toList();

        PageInfo pageInfo = new DefaultPageInfo(
            !edges.isEmpty() ? edges.get(0).getCursor() : null,
            !edges.isEmpty() ? edges.get(edges.size() - 1).getCursor() : null,
            anchor != null,           // hasPreviousPage (approx)
            hasMore                   // hasNextPage
        );
        return new DefaultConnection<>(edges, pageInfo);
    }
}

// Repository method using JPQL keyset filter
interface PostRepository extends JpaRepository<Post, String> {
    @Query("""
        SELECT p FROM Post p
        WHERE (:status IS NULL OR p.status = :status)
          AND (:createdAt IS NULL
               OR (p.createdAt, p.id) < (:createdAt, :id))
        ORDER BY p.createdAt DESC, p.id DESC
        """)
    List<Post> findPage(
        @Param("status")    PostStatus status,
        @Param("createdAt") Instant    createdAt,
        @Param("id")        String     id,
        Pageable            pageable);
}

// The opaque cursor the client sees is e.g.
//   eyJjIjoxNzI1OTgwMDAwMDAwLCJpIjoicG9zdF8wMWoyM2EifQ==
// which base64-decodes to {"c": 1725980000000, "i": "post_01j23a"}.
// The keyset approach stays correct under concurrent INSERT/DELETE where
// offset pagination would skip or duplicate rows.

The default behavior for unhandled exceptions in Spring for GraphQL is conservative — the engine logs the full stack trace server-side but returns a generic "INTERNAL_ERROR" message to the client. This prevents information leakage but makes every error look the same to the client.

To give clients actionable error information, extend `DataFetcherExceptionResolverAdapter` and map each domain exception to a specific `ErrorType` with safe metadata in the `extensions` map.

```java
@Component
public class DomainExceptionResolver extends DataFetcherExceptionResolverAdapter {

    @Override
    protected GraphQLError resolveToSingleError(Throwable ex,
                                                 DataFetchingEnvironment env) {
        if (ex instanceof BookNotFoundException e) {
            return GraphqlErrorBuilder.newError(env)
                .message(e.getMessage())
                .errorType(ErrorType.NOT_FOUND)
                .extensions(Map.of("code", "NOT_FOUND",
                                   "resourceId", e.getBookId()))
                .build();
        }
        if (ex instanceof AccessDeniedException) {
            return GraphqlErrorBuilder.newError(env)
                .message("Insufficient permissions")
                .errorType(ErrorType.FORBIDDEN)
                .extensions(Map.of("code", "FORBIDDEN"))
                .build();
        }
        return null;  // unhandled → default INTERNAL_ERROR behavior
    }
}
```

The `extensions` map is the machine-readable contract between server and client. Clients use `error.extensions.code` for programmatic branching — "if FORBIDDEN, redirect to login; if NOT_FOUND, show empty state." Never rely on `message` for programmatic logic because messages are human-readable and may change. The `path` field (auto-populated by the engine) tells the client exactly which field in the query failed, enabling granular error UI.

The top-level `errors` array handles unexpected failures — resolver bugs, permission violations, data not found. But for **expected** failures like input validation, a better pattern exists: return errors as structured data in the mutation payload.

The difference matters for client UX. A validation failure like "title must be at least 3 characters" should map to a specific form field, not appear as a generic toast notification. Mutation payload types with a `UserError` list make this possible.

```graphql
type Mutation {
  createBook(input: CreateBookInput!): CreateBookPayload!
}

type CreateBookPayload {
  book: Book                  # null on validation failure
  errors: [UserError!]!       # empty list on success
}

type UserError {
  field: String               # "title", "authorId" — maps to the input field
  message: String!
}
```

The resolver validates before acting. If validation fails, it returns the payload with errors and a null book — no exception thrown, no entry in the top-level `errors` array.

```java
@MutationMapping
public CreateBookPayload createBook(@Argument CreateBookInput input) {
    List<UserError> errors = validator.validate(input);
    if (!errors.isEmpty()) {
        return new CreateBookPayload(null, errors);  // errors as data
    }
    Book book = bookService.create(input);
    return new CreateBookPayload(book, List.of());   // success
}
```

This separation keeps two error categories distinct. Validation failures (`UserError` in payload) are expected, recoverable, and map to UI fields. System failures (top-level `errors` array) are unexpected, not recoverable by the user, and trigger error toasts or retries. Mixing them forces clients to string-parse error messages to figure out which category they're looking at.

The most dangerous interaction between errors and schema design is **null bubbling**. When a resolver throws an error, GraphQL sets the field's value to `null`. If that field is declared non-null (`!`), the null is invalid — so GraphQL nulls the parent object instead. If the parent is also non-null, it nulls the grandparent. This cascades up the tree until it reaches a nullable field or the root.

A concrete scenario: a `books` query returns 50 results. One book's `author` resolver throws. If the schema declares `author: Author!` and the books list is `[Book!]!`, here's what happens — the author becomes null (violates `Author!`), so the Book becomes null (violates `[Book!]!`), so the entire `books` field becomes null, which means `data.books` is null in the response. The client gets zero books because one author resolver failed.

The schema design determines the blast radius of any individual resolver failure. Make fields non-null only when you're confident the resolver never fails — `id: ID!` is safe, `author: Author!` is risky because it depends on a separate database call.

```json
{
  "data": { "books": null },
  "errors": [
    {
      "message": "Failed to load author for book 42",
      "path": ["books", 41, "author"],
      "extensions": { "classification": "INTERNAL_ERROR" }
    }
  ]
}
```

The response above shows the full impact — 49 successfully resolved books were erased because of one failure. Making `author` nullable would have preserved all 49 books, with only book 42 showing a null author. This is why nullable-by-default is the safer schema design strategy.

`@GraphQlTest` is the GraphQL equivalent of `@WebMvcTest`. It loads only the specified controller, the schema files, and any `DataFetcherExceptionResolver` beans. Services and repositories are mocked with `@MockBean`. This narrow scope means tests run in under a second and catch the most common bugs: method names that don't match schema fields, argument type mismatches, and missing `@SchemaMapping` resolvers.

```java
@GraphQlTest(BookController.class)
class BookControllerTest {

    @Autowired
    private GraphQlTester graphQlTester;

    @MockBean
    private BookService bookService;

    @Test
    void books_returnsAllBooks() {
        given(bookService.findAll()).willReturn(List.of(
            new Book(1L, "Clean Code", BookStatus.PUBLISHED),
            new Book(2L, "Refactoring", BookStatus.PUBLISHED)
        ));

        graphQlTester.document("""
            query {
              books {
                id
                title
                status
              }
            }
            """)
            .execute()
            .path("books").entityList(Book.class).hasSize(2)
            .path("books[0].title").entity(String.class)
                .isEqualTo("Clean Code");
    }
}
```

The `.path()` API uses JSONPath-like syntax to assert on specific fields without comparing entire JSON blobs. This is critical for maintainability — a test that asserts on the full JSON response breaks every time you add a field, even if the change is backward-compatible. Path-based assertions focus on the contract that matters.

Mutation tests verify that write operations return the correct payload and that error conditions produce properly classified GraphQL errors. The `.errors()` API lets you inspect error classifications and extensions without parsing raw JSON.

```java
@Test
void createBook_withValidInput_returnsPayload() {
    given(bookService.create(any())).willReturn(
        new Book(3L, "DDD", BookStatus.DRAFT)
    );

    graphQlTester.document("""
        mutation {
          createBook(input: { title: "DDD", authorId: "1" }) {
            book { id title }
            errors { field message }
          }
        }
        """)
        .execute()
        .path("createBook.book.title").entity(String.class)
            .isEqualTo("DDD")
        .path("createBook.errors").entityList(Object.class).hasSize(0);
}

@Test
void book_notFound_returnsTypedError() {
    given(bookService.findById(99L))
        .willThrow(new BookNotFoundException(99L));

    graphQlTester.document("""
        query { book(id: 99) { id title } }
        """)
        .execute()
        .errors()
        .satisfy(errors -> {
            assertThat(errors).hasSize(1);
            assertThat(errors.get(0).getExtensions())
                .containsEntry("classification", "NOT_FOUND");
        });
}
```

The error test verifies that your `DataFetcherExceptionResolver` correctly maps `BookNotFoundException` to a `NOT_FOUND` classification. Without this test, you might ship a resolver that throws the right exception but produces a generic `INTERNAL_ERROR` classification because the resolver bean wasn't loaded in the test context. The `.satisfy()` method gives you full AssertJ access to the error list, so you can verify classifications, extensions, and paths precisely.

For production confidence, integration tests exercise the complete request pipeline — HTTP transport, security filters, real repositories, DataLoader batching, and exception resolvers. `@SpringBootTest` with a random port plus `@AutoConfigureHttpGraphQlTester` gives you an `HttpGraphQlTester` that sends real HTTP requests.

```java
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@AutoConfigureHttpGraphQlTester
class BookGraphQlIntegrationTest {

    @Autowired
    private HttpGraphQlTester httpGraphQlTester;

    @Test
    void books_withAuth_returnsBooks() {
        httpGraphQlTester
            .mutate()
            .header(HttpHeaders.AUTHORIZATION, "Bearer " + testJwt())
            .build()
            .document("{ books { id title } }")
            .execute()
            .path("books").entityList(Book.class)
                .hasSizeGreaterThan(0);
    }

    @Test
    void createBook_withoutAuth_returnsForbidden() {
        httpGraphQlTester
            .document("""
                mutation {
                  createBook(input: { title: "Test", authorId: "1" }) {
                    book { id }
                  }
                }
                """)
            .execute()
            .errors()
            .satisfy(errors ->
                assertThat(errors.get(0).getExtensions())
                    .containsEntry("classification", "FORBIDDEN")
            );
    }
}
```

The `.mutate().header().build()` pattern creates a modified tester instance with authentication headers, simulating authenticated versus anonymous requests. This verifies that your `SecurityFilterChain` correctly blocks unauthenticated access and that `@PreAuthorize` annotations produce the right error classification.

Keep a small set of raw `WebTestClient` tests alongside GraphQL tester tests for transport-level concerns — content type validation, CORS headers, and malformed request body handling. These edge cases are invisible to `GraphQlTester` because it operates at the GraphQL execution level, not the HTTP level.

// Same "get user with last 5 orders" request, three ways.

// ==== REST (fetch, JSON) =================================================
const user = await fetch(`/v1/users/${id}`).then(r => r.json());
const orders = await fetch(`/v1/users/${id}/orders?limit=5`).then(r => r.json());
const items = await Promise.all(
  orders.map((o: any) => fetch(`/v1/orders/${o.id}/items`).then(r => r.json()))
);
// ~3 + N round-trips, client stitches.

// ==== GraphQL (fetch, one query) =========================================
const gql = `query($id: ID!) {
  user(id: $id) {
    id displayName
    orders(last: 5) {
      id total { amount currency }
      items { quantity product { sku name thumbnailUrl } }
    }
  }
}`;
const { data } = await fetch('/graphql', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ query: gql, variables: { id } }),
}).then(r => r.json());
// 1 round-trip, shape matches UI.

// ==== gRPC (via gRPC-Web proxy for browsers) =============================
import { UserServiceClient } from './generated/user_service_grpc_web_pb';
const client = new UserServiceClient('https://api.example.com', null, null);
const req = new GetUserWithOrdersRequest();
req.setUserId(id); req.setLast(5);
const res = await new Promise((ok, fail) =>
  client.getUserWithOrders(req, {}, (err, resp) => err ? fail(err) : ok(resp)));
// Strong types on the client, binary protobuf on the wire, but:
//  - Needs generated code (build step)
//  - Needs gRPC-Web proxy (Envoy) for browsers
//  - No CDN caching of responses
// Best for service-to-service, not typically for browser clients.
